#!/usr/bin/env python3
"""Russia flagship course data 4: RU-25 to RU-31. Own wording. HELD for a lawyer's check."""

COURSES = []

COURSES.append(dict(
 id='RU-25', title='Construction', level='L4 Practitioner',
 summary='Learn how a small building project moves from brief to handover: quantities, cost build-up, programme, site safety, quality checks and records. You practise on a small house extension and a site office.',
 outcomes=[
  ('Understand', 'Explain the stages of a building project from brief and design to permits, construction, inspection and handover.'),
  ('Apply', 'Calculate concrete, brick and reinforcement quantities for a simple structure, with a waste allowance.'),
  ('Analyse', 'Break a project cost into labour, materials, plant, overhead and contingency and find the largest cost risks.'),
  ('Evaluate', 'Judge a site against safety and quality checklists and decide which hazards must stop work.'),
  ('Create', 'Build a programme, a cost plan and a handover file for a small building job.'),
 ],
 task='Prepare a quantity list, cost plan, 10-week programme, site safety plan and inspection log for a 6 m by 5 m single-storey extension.',
 condition='Given a simple drawing, a local material price list in RUB, a spreadsheet, and 6 hours of working time, with a mentor available for questions.',
 standard='Quantities within 5 percent of the mentor check, costs add up with no arithmetic error, every major hazard has a control, and at least 8 of 10 check answers are right.',
 who='Beginners, site assistants, small contractors and owners who want to manage a small build with understanding.',
 req='Basic arithmetic, a spreadsheet, and the ability to read a simple plan. No licence is needed to study.',
 safety='Construction is regulated. Design, permits, builder licensing or membership of a self-regulating organisation, structural calculations, fire rules and site safety are set by the relevant federal rules and the competent authority. This course teaches understanding only; it does not replace a licensed designer, engineer or safety officer. Check with the competent Russian authority and a local adviser before starting any real work. Work at height, excavation and electricity can kill: never rely on this course for safety decisions.',
 evidence='Evidence products: quantity list, cost plan, programme chart, site safety plan, inspection log and handover file.',
 modules=[
  ('How a building project runs', 'Understand', 3,
   'A project passes through clear stages, and each stage ends with a decision and a record. Missing a stage is the usual cause of delay and dispute.',
   ['Name the stages: brief, design, permit and approvals, tender or pricing, construction, inspection, handover.',
    'Explain who does what: owner, designer, main contractor, subcontractors, supervisor and the inspecting authority.',
    'Show why records matter: a hidden item such as buried reinforcement must be inspected before it is covered.',
    'Distinguish a contract type: fixed price carries price risk for the contractor, cost-plus carries it for the owner.'],
   'A 30 m2 extension: design 3 weeks, approvals 4 weeks, construction 10 weeks, handover 1 week. Total 18 weeks. If approvals slip by 2 weeks, handover moves from week 18 to week 20 unless work overlaps.',
   'Draw the stage chain for the extension and mark where an inspection must occur before work is covered.',
   'All seven stages in order, with at least three hold points and one named record per stage.'),
  ('Reading drawings and measuring', 'Apply', 4,
   'Quantities come from drawings. Scale, units and levels must be read correctly or every later number is wrong.',
   ['Convert scale: at 1:50, 1 cm on paper is 0.5 m on site.',
    'Read plans, sections and details, and list the dimensions you need: length, width, height, thickness.',
    'Measure in metric units and keep one unit per line in the take-off sheet.',
    'Check a drawing for conflicts, such as a door in a wall that is drawn as solid.'],
   'A wall shown 12 cm long on a 1:50 plan is 6.0 m. At a height of 2.7 m and thickness 0.38 m the wall volume is 6.0 x 2.7 x 0.38 = 6.16 m3 before deducting a 0.9 m by 2.1 m door (0.72 m3).',
   'Measure the wall volumes of the extension from a given plan and deduct two openings.',
   'Volumes within 5 percent of the mentor figure and every deduction listed.'),
  ('Quantities for concrete, masonry and steel', 'Apply', 5,
   'Bills of quantities turn geometry into orders. Waste and overbreak must be added honestly.',
   ['Concrete volume = length x width x depth; add 5 percent for spillage and uneven ground.',
    'Block or brick count = wall area x units per m2, minus openings, plus 5 percent breakage.',
    'Reinforcement: total bar length x mass per metre; add 10 percent for laps and cuts.',
    'Order to the supplier unit, for example whole cubic metres or full pallets, and say how you rounded.'],
   'A strip foundation 22 m long, 0.5 m wide, 0.4 m deep: 22 x 0.5 x 0.4 = 4.4 m3; plus 5 percent = 4.62 m3, order 4.7 m3. Reinforcement: 4 bars x 22 m = 88 m; at 0.89 kg/m = 78.3 kg; plus 10 percent = 86.2 kg.',
   'Compute foundation, wall and slab quantities for the extension and produce an order list.',
   'Every line shows formula, allowance and rounding; total concrete within 5 percent of the check.'),
  ('Cost build-up and pricing', 'Analyse', 4,
   'A price is built, not guessed. Each rate has labour, material, plant and a share of overhead and risk.',
   ['Build a unit rate: material cost + labour hours x hourly rate + plant + waste.',
    'Add site overhead (for example 8 percent), head-office overhead and contingency (for example 5 to 10 percent).',
    'Separate fixed costs from quantity-driven costs so a change in scope can be priced.',
    'Compare two quotes by line, not by total, to find what was left out.'],
   'Block wall rate per m2: blocks 1.0 m2 at 520 RUB, mortar 85 RUB, labour 0.9 h x 450 RUB = 405 RUB. Subtotal 1010 RUB per m2. With 8 percent overhead and 5 percent contingency: 1010 x 1.08 x 1.05 = 1145 RUB per m2.',
   'Price 40 m2 of block wall with a rate sheet and compare it with a second quote.',
   'Rate shows each component; total correct; at least two omissions found in the second quote.'),
  ('Programme and resources', 'Create', 4,
   'A programme sequences work and shows which delays move the finish date. The critical path is the longest chain of dependent tasks.',
   ['List tasks, durations and dependencies, for example walls cannot start before the foundation has cured.',
    'Find the critical path by adding durations along each chain.',
    'Level resources so a crew is not planned on two places at once.',
    'Add float and weather allowance, and update the plan weekly.'],
   'Tasks: excavate 3 days, foundation 4, cure 7, walls 12, roof 8, finishes 15. Chain total = 49 working days, about 10 weeks. A 3-day delay to the walls moves the finish by 3 days; a 3-day delay to a task with 5 days float does not.',
   'Build a 10-week programme and mark the critical path.',
   'Dependencies are correct, the critical path total is right, and a weekly update note exists.'),
  ('Site safety and hazard control', 'Evaluate', 4,
   'Construction has high rates of falls, collapses, electric shock and struck-by accidents. Controls are chosen from the most effective type downward.',
   ['Order of control: remove the hazard, replace it, guard it, organise work, then protective equipment as the last layer.',
    'Work at height: edge protection, secured ladders, trained workers, no work in high wind or ice.',
    'Excavation: shoring or safe slope, spoil kept back from the edge, a safe way out for people.',
    'Daily checks: access, lifting gear, electrical leads, guards, first-aid kit and emergency route.'],
   'A trench 1.8 m deep with 1.0 m of spoil placed at the edge is unsafe. Controls: shore the sides, move spoil at least 1 m back, ladder every 7 m of trench length, daily inspection signed by the supervisor.',
   'Walk a photo or site case, list ten hazards and choose a control for each.',
   'All high-risk hazards have a control higher than protective equipment, and stop-work triggers are named.'),
  ('Quality, inspection and compliance', 'Evaluate', 4,
   'Quality is checked against the drawing and the rules at set points. Compliance is proved by records, not memory.',
   ['Check tolerances: wall plumb within 10 mm over 3 m, floor level within 5 mm over 2 m, as the project specification states.',
    'Test concrete: slump test on delivery and cube samples as the specification requires.',
    'Keep hold-point records, delivery notes, test results and photographs with dates.',
    'Know that permits, approvals and inspections are required by the relevant federal rules and the competent authority; ask a licensed adviser.'],
   'A 3 m straightedge on a floor slab shows a 9 mm gap against a 5 mm tolerance: the item fails, is recorded, repaired and rechecked, and the recheck is signed and dated.',
   'Complete an inspection log for three hold points and mark one failure with a corrective action.',
   'Each entry has date, item, result, inspector and action; failures are not hidden.'),
  ('Handover, cost control and records', 'Create', 3,
   'A job ends cleanly with a defects list, final account and a file the owner can keep.',
   ['Track budget against actual weekly and explain variances.',
    'Control changes: price each variation and get written agreement before work.',
    'Prepare the handover file: as-built drawings, test results, warranties, maintenance notes.',
    'Hold back a retention amount until defects are cleared.'],
   'Contract 1,200,000 RUB; variations +85,000 RUB; retention 5 percent of 1,285,000 = 64,250 RUB held until defects are fixed. Final payment on completion = 1,285,000 - 64,250 = 1,220,750 RUB less earlier payments.',
   'Prepare a final account and handover file index for the extension.',
   'Arithmetic is right, every variation has a written record, and the file lists at least eight document types.'),
 ],
 quiz=[
  ('Why is a hold point used before covering reinforcement?', 'Because it cannot be inspected once covered; an inspector must check and sign first.'),
  ('At scale 1:50, what real length is 8 cm on paper?', '4.0 m.'),
  ('A foundation needs 6.3 m3 of concrete. Give an order with 5 percent allowance.', '6.3 x 1.05 = 6.615, order about 6.7 m3.'),
  ('Name the order of hazard controls.', 'Remove, replace, guard, organise work, then protective equipment.'),
  ('What is the critical path?', 'The longest chain of dependent tasks; any delay on it delays the finish.'),
  ('Why compare quotes by line?', 'To find omitted items and unequal assumptions that a total hides.'),
  ('Which contract type puts price risk on the contractor?', 'Fixed price.'),
  ('A trench is 1.8 m deep. Give two controls.', 'Shoring or safe slope, and spoil kept back from the edge with a safe exit.'),
  ('Who should approve design and structural calculations?', 'A licensed designer or engineer as required by the relevant federal rules and the competent authority.'),
  ('Why price variations before work?', 'To avoid disputes and to keep the budget under control.'),
 ],
 rubric=[
  ('Quantities', 'Formulas missing or errors above 5 percent.', 'Within 5 percent with allowances shown.', 'Also states assumptions and cross-checks totals.'),
  ('Cost plan', 'Totals only, no unit rates.', 'Rates with overhead and contingency, correct arithmetic.', 'Also tests sensitivity to a 10 percent price rise.'),
  ('Programme', 'No dependencies.', 'Correct critical path and float.', 'Also resource-levelled and updated weekly.'),
  ('Safety', 'Hazards listed without controls.', 'Each high hazard has an effective control.', 'Also gives stop-work triggers and emergency steps.'),
  ('Records and compliance', 'Few records, no mention of permits.', 'Inspection log and handover file complete; permit route named.', 'Also traces each record to a rule check by a licensed adviser.'),
 ],
 ladder=[
  'L1 Basic: Name the main building stages and common site hazards (note: awareness only).',
  'L2 Awareness: Explain what a drawing, a permit and an inspection are for.',
  'L3 Foundation: Calculate simple areas, volumes and material counts with waste.',
  'L4 Practitioner: Build a cost plan, programme and inspection log for a small job.',
  'L5 Specialist: Manage a small site team, subcontract packages and weekly cost control.',
  'L6 Advanced: Plan multi-trade projects, judge risk and manage variations and claims.',
  'L7 Super expert: Design delivery systems for large portfolios and mentor leaders (needs licensed qualifications).',
 ],
 jobs=[
  ('Site assistant', 'Records deliveries, checks, measurements and daily site notes.'),
  ('Quantity assistant', 'Measures drawings and builds bills of quantities.'),
  ('Site supervisor', 'Directs crews, safety and quality on a small project.'),
  ('Estimator assistant', 'Builds unit rates and compares quotes.'),
  ('Small contractor', 'Runs small building jobs with licensed advice where required.'),
 ],
 next='Next courses: Real Estate, Interior Design, and Occupational Health and Safety.',
))

COURSES.append(dict(
 id='RU-26', title='Mining', level='L4 Practitioner',
 summary='Learn how a small mining operation is planned and controlled: resource and grade, drilling and blasting basics, haulage, ventilation, safety management and records. The course teaches planning arithmetic and compliance thinking, not operation.',
 outcomes=[
  ('Understand', 'Explain the mine life cycle from exploration to closure and the role of licences and inspection.'),
  ('Apply', 'Calculate tonnes, grade and metal content for a simple orebody block.'),
  ('Analyse', 'Break unit cost per tonne into drilling, blasting, loading, haulage and processing.'),
  ('Evaluate', 'Judge a hazard register for ground, ventilation, explosives and machinery risks.'),
  ('Create', 'Build a short-interval plan, a haulage cycle estimate and a safety and compliance file.'),
 ],
 task='Prepare a block tonnage and grade estimate, a haulage cycle calculation, a hazard register and a compliance checklist for a small open-pit quarry.',
 condition='Given a block model extract, equipment data, a spreadsheet and 6 hours of working time, with a mentor to review.',
 standard='Tonnage and metal content within 3 percent of the key, cycle time arithmetic correct, every high hazard has a control, and at least 8 of 10 check answers are right.',
 who='Learners entering mining support, quarry technicians, planners and owners who want to understand the work.',
 req='Basic arithmetic, a spreadsheet and the ability to read a table. No mining experience is needed to study.',
 safety='Mining is among the most regulated and dangerous sectors. Subsurface use rights, licences, environmental approval, explosives handling, mine rescue and inspection are controlled by the relevant federal rules and the competent authority. This course does not authorise any person to work underground, handle explosives or run a mine. Check with the competent Russian authority and a local adviser before any real activity. Use only trained and certified persons for blasting, ventilation and ground control. Nothing here predicts a profit.',
 evidence='Evidence products: block estimate sheet, haulage calculation, hazard register, ground and ventilation checklist, compliance checklist.',
 modules=[
  ('Mine life cycle and licensing', 'Understand', 3,
   'A mine passes through exploration, assessment, development, production and closure, and each stage needs permission and records.',
   ['Name stages: exploration, resource estimate, feasibility, development, production, closure and rehabilitation.',
    'Explain why subsurface use rights and approvals come before any works.',
    'Distinguish a resource (geological estimate) from a reserve (economically and legally mineable part).',
    'Explain why closure cost is planned from the start.'],
   'A deposit has 2,000,000 t in the resource; after dilution and legal limits only 1,500,000 t are reserve, which is 75 percent. Planning on the larger number would overstate output by 33 percent.',
   'Draw the life cycle and mark the permit or approval needed at each stage.',
   'All stages in order with at least four named approvals or records.'),
  ('Geology, sampling and grade', 'Apply', 4,
   'Grade is the share of valuable material in rock. A sample must represent the whole, or the estimate is wrong.',
   ['Define grade as grams per tonne or percent, and state which unit is used.',
    'Take samples at set spacing and keep a chain of custody for each bag.',
    'Compute a weighted average grade from lengths or tonnes.',
    'Explain nugget effect and why a few samples can mislead.'],
   'Three drill intervals: 2 m at 4.0 g/t, 3 m at 1.0 g/t, 1 m at 7.0 g/t. Weighted grade = (8 + 3 + 7) / 6 = 3.0 g/t.',
   'Calculate weighted grade for a drill hole table of six intervals.',
   'Correct weighted average and units, with the sample record complete.'),
  ('Block tonnage and metal content', 'Apply', 4,
   'Tonnes are volume times density. Metal content is tonnes times grade, reduced by recovery.',
   ['Tonnes = volume (m3) x density (t/m3).',
    'Metal (g) = tonnes x grade (g/t); recovered metal = metal x recovery percent.',
    'Apply dilution and mining loss as percentages and keep them visible.',
    'Reconcile plan against production each week.'],
   'Block 50 m x 30 m x 10 m = 15,000 m3 at density 2.7 t/m3 = 40,500 t. At 3.0 g/t, metal = 121,500 g. With mining loss 5 percent and recovery 90 percent: 121,500 x 0.95 x 0.90 = 103,883 g.',
   'Compute tonnes and recovered metal for three blocks and compare plan with actual.',
   'Within 3 percent of key; every factor shown.'),
  ('Drilling and blasting basics', 'Understand', 3,
   'Blasting breaks rock but is the most dangerous task in the mine. Only certified persons may do it.',
   ['Explain burden and spacing, and why they set fragmentation.',
    'Compute powder factor as explosive kg per tonne or m3 of rock.',
    'Describe exclusion zones, warnings and misfire rules in general terms.',
    'Recognise that storage, transport and use of explosives are strictly controlled by the relevant federal rules and the competent authority.'],
   'A blast breaks 12,000 m3 using 3,600 kg explosive: powder factor = 0.30 kg/m3. Changing to 4,200 kg gives 0.35 kg/m3, a 17 percent increase in explosive cost.',
   'Calculate the powder factor for three blast designs and compare cost.',
   'Correct factors; safe-distance rules named as set by the competent authority.'),
  ('Loading and haulage', 'Analyse', 4,
   'Haulage is often the biggest cost. A cycle time sets truck output.',
   ['Cycle = load + haul + dump + return + queue.',
    'Trips per hour = 60 / cycle minutes; output = trips x payload x availability.',
    'Match trucks to loader: too few trucks idle the loader, too many queue.',
    'Check road grade, width and condition as a control on speed and safety.'],
   'Cycle: load 4 + haul 9 + dump 1 + return 7 + queue 2 = 23 min. Trips/h = 2.6; payload 30 t; availability 85 percent: 2.6 x 30 x 0.85 = 66 t/h per truck. For 400 t/h need 6 trucks.',
   'Compute truck numbers for a target of 350 t/h.',
   'Cycle, trips and fleet all correct and rounded up.'),
  ('Ground control, ventilation and dust', 'Evaluate', 4,
   'Falls of ground, bad air and dust cause severe harm. Controls are inspection, support, ventilation and measurement.',
   ['Check slope or roof conditions at every shift start and after blasts or rain.',
    'Explain airflow: air demand depends on people, diesel machines and gases.',
    'Measure gas and dust with calibrated instruments and keep the records.',
    'Prepare an emergency plan: alarms, refuge, rescue contacts and drills.'],
   'A face needs 0.06 m3/s of air per kW of diesel engine. Two 150 kW machines = 300 kW x 0.06 = 18 m3/s required. A fan delivering 15 m3/s is short by 3 m3/s, so work must be reduced or the fan upgraded.',
   'Review a hazard register and rate each hazard by likelihood and severity.',
   'High risks have engineering controls first; stop-work triggers are written.'),
  ('Cost per tonne and economics', 'Analyse', 4,
   'Unit cost shows where money goes. A cutoff grade is the lowest grade that pays for mining and processing.',
   ['Split cost: drill, blast, load, haul, process, overhead, closure provision.',
    'Cutoff grade = cost per tonne / (price per g x recovery).',
    'Run a sensitivity of 10 percent on price, grade and cost.',
    'State that prices move and no profit is promised.'],
   'Costs total 2,400 RUB per tonne. With price 3,500 RUB per g and recovery 90 percent: cutoff = 2,400 / (3,500 x 0.9) = 0.76 g/t. Rock below 0.76 g/t is waste in this model.',
   'Calculate cutoff grade and test a 10 percent cost rise.',
   'Formula applied correctly; sensitivity table complete.'),
  ('Environment, closure and compliance file', 'Create', 3,
   'A mine must manage water, waste rock, dust and closure. A compliance file proves it.',
   ['List environmental duties: water discharge, waste storage, dust, land reclamation.',
    'Keep monitoring logs and permit conditions in one register.',
    'Plan closure: reshape, cover, revegetate and monitor.',
    'Name who inspects and how often according to the relevant federal rules.'],
   'Closure provision of 150 RUB per tonne on 500,000 t = 75,000,000 RUB set aside over mine life; ignoring it would hide a large future cost.',
   'Build a compliance register with ten items, owner, frequency and record.',
   'Every item has an owner, a frequency and a named record.'),
 ],
 quiz=[
  ('What is the difference between resource and reserve?', 'A resource is a geological estimate; a reserve is the part that is economic and legally mineable.'),
  ('Block 20 x 20 x 5 m at density 2.5: how many tonnes?', 'Volume is 20 x 20 x 5 = 2,000 m3, then multiply by density 2.5 to get 5,000 t; show the unit at each step so the result can be checked.'),
  ('Weighted grade of 1 m at 2 g/t and 3 m at 6 g/t?', '(1 x 2 + 3 x 6) / 4 = 20 / 4 = 5 g/t. A plain average of 2 and 6 would give 4 g/t, which is wrong because the intervals differ in length.'),
  ('Define powder factor.', 'Explosive mass used per unit of rock broken, for example kg per m3; 3,600 kg over 12,000 m3 gives 0.30 kg/m3, and it is used to compare blast designs and cost.'),
  ('Cycle time is 20 min. How many trips per hour?', '60 / 20 = 3 trips per hour; with a 30 t payload and 85 percent availability that is about 76 t/h per truck.'),
  ('Why shift-start ground inspection?', 'Conditions change after blasts, rain and time; falls of ground are a leading cause of harm.'),
  ('Who may handle blasting?', 'Only certified persons authorised under the relevant federal rules and the competent authority; a learner on this course studies the arithmetic but never handles explosives.'),
  ('Cutoff grade formula?', 'Cost per tonne divided by price per unit times recovery; for 2,400 RUB per tonne, 3,500 RUB per g and 90 percent recovery it is 0.76 g/t.'),
  ('Why plan closure cost early?', 'It is a large future liability that must be provided for from the start; 150 RUB per tonne on 500,000 t is 75,000,000 RUB, and ignoring it hides real cost.'),
  ('Does this course allow you to run a mine?', 'No; licences, subsurface use rights and certified competent persons are required, and this course teaches planning arithmetic and compliance thinking only.'),
 ],
 rubric=[
  ('Estimate accuracy', 'Errors above 3 percent or units mixed.', 'Within 3 percent with units shown.', 'Also states uncertainty and sampling limits.'),
  ('Haulage calculation', 'Cycle parts missing.', 'Cycle, trips and fleet correct.', 'Also tests queue and availability changes.'),
  ('Hazard control', 'Hazards listed only.', 'Each high hazard has an engineering control and a trigger.', 'Also includes rescue and drill plan.'),
  ('Economics', 'No sensitivity.', 'Cutoff and 10 percent sensitivity done.', 'Also shows break-even price and warns of price risk.'),
  ('Compliance', 'No register.', 'Register with owners and records.', 'Also maps each item to the competent authority with adviser check.'),
 ],
 ladder=[
  'L1 Basic: Name the stages of a mine and its main hazards such as falls of ground, bad air, dust and explosives (awareness only, no site work).',
  'L2 Awareness: Explain grade, tonnes and why licences, subsurface use rights and inspection matter before any works begin.',
  'L3 Foundation: Calculate tonnes, grade and recovered metal for a simple block, showing density, loss and recovery factors in the sheet.',
  'L4 Practitioner: Build haulage, cost and hazard files for a small quarry, with a cycle calculation, a cost split and a hazard register.',
  'L5 Specialist: Plan short-interval production and reconcile plan with actual each week, explaining every variance above 3 percent.',
  'L6 Advanced: Optimise pit or stope design, cutoff and fleet with risk review.',
  'L7 Super expert: Lead mine planning and safety systems for large operations (needs certified qualifications).',
 ],
 jobs=[
  ('Mine technician assistant', 'Records samples, measurements and shift data.'),
  ('Planning assistant', 'Builds block tonnage and haulage sheets.'),
  ('Quarry supervisor trainee', 'Supports a certified supervisor on a small site.'),
  ('Environmental records clerk', 'Maintains monitoring and permit registers.'),
  ('Safety coordinator trainee', 'Maintains hazard registers and drills under a certified lead.'),
 ],
 next='Next courses: Oil and Gas, Occupational Health and Safety, and Environmental Management.',
))

COURSES.append(dict(
 id='RU-27', title='Medical Waste Disposal', level='L4 Practitioner',
 summary='Learn how medical waste is classified, separated, packed, stored, moved and recorded in a clinic or small hospital. The course teaches the management system and records, and stresses licensing and infection safety.',
 outcomes=[
  ('Understand', 'Explain the hazard classes of medical waste and why each class is handled differently.'),
  ('Apply', 'Sort a list of items into the correct class and container colour system of the facility.'),
  ('Analyse', 'Calculate waste generation per bed or per visit and identify the biggest source for reduction.'),
  ('Evaluate', 'Judge a storage room, a transport route and a waste log against a checklist.'),
  ('Create', 'Build a waste management plan with training, spill response and a record register.'),
 ],
 task='Prepare a waste classification chart, a weekly generation estimate, a storage and handover checklist, and a spill and needle-stick response card for a 20-bed clinic.',
 condition='Given a list of 30 items, a clinic profile, a spreadsheet and 5 hours of working time, with a mentor to review.',
 standard='At least 28 of 30 items sorted correctly, weights and containers calculated without error, every checklist item tied to a record, and at least 8 of 10 check answers right.',
 who='Clinic staff, cleaners, facility managers and learners who want to work safely with waste.',
 req='Basic arithmetic and a spreadsheet. No medical qualification is needed to study the system.',
 safety='Medical waste can carry infection, sharps injury, chemical and radiological risk. Classification, packaging, on-site treatment, transport and final disposal are regulated by the relevant federal rules and the competent authority, and carrying or treating waste usually needs a licence. This course does not authorise anyone to transport, treat or dispose of waste. Use only licensed contractors for hazardous classes. Check with the competent Russian authority and a local adviser. After a needle-stick or exposure, seek medical help at once.',
 evidence='Evidence products: classification chart, generation estimate, storage checklist, handover log, response card and training record.',
 modules=[
  ('Hazard classes and why they matter', 'Understand', 3,
   'Waste is split by risk so that low-risk waste does not become expensive hazardous waste and dangerous waste is never mixed in.',
   ['Name the groups in general terms: non-hazardous, infectious, highly infectious, chemical and drug, and radiological waste.',
    'Explain that the national rules fix the class system; the facility must use the current version.',
    'Show the cost of mixing: one infectious item in a general bin turns the whole bin into hazardous waste.',
    'List who is at risk: staff, cleaners, patients, drivers, the public.'],
   'A clinic makes 50 kg of waste per day, of which 10 percent is infectious. If all is mixed, 50 kg is treated as infectious. If sorted, only 5 kg is. At 40 RUB per kg treatment this saves 45 x 40 = 1,800 RUB per day.',
   'Match 15 items to hazard groups and note the rule that sets each group.',
   'At least 14 of 15 correct, with the reason stated.'),
  ('Segregation at the point of use', 'Apply', 4,
   'The safest sorting happens where waste is made. Bins, colours and labels must be close and clear.',
   ['Place the right container in each room: sharps box, infectious bag, general bin.',
    'Never recap needles; drop the whole device into a puncture-proof sharps box.',
    'Fill containers only to the line, usually three quarters, then close.',
    'Label with date, room, and waste class.'],
   'A sharps box of 5 L is closed at 75 percent = 3.75 L. If a ward uses 6 boxes per week, a stock of 10 per week with spare is needed.',
   'Plan bins and labels for a consulting room, a procedure room and a ward.',
   'No room lacks a sharps box and each label has date and class.'),
  ('Packaging, labelling and on-site transport', 'Apply', 3,
   'Safe containers stop spills and injuries. Moving waste inside a building needs set routes and times.',
   ['Use leak-proof, sealed, labelled bags and rigid boxes.',
    'Move waste on a set route, away from patients and food, using a closed cart.',
    'Wear gloves and protective clothing and wash hands afterwards.',
    'Do not compress or hand-sort sealed bags.'],
   'A cart holds 6 bags of 8 kg = 48 kg. A route of 120 m at 0.8 m/s takes 150 s one way; 4 trips per day is about 20 minutes of staff time.',
   'Design a route and timetable for a 20-bed clinic.',
   'Route avoids waiting areas and kitchens and times fit the shift.'),
  ('Storage and handover', 'Evaluate', 4,
   'Waste is stored briefly in a locked, cool, cleanable room. Handover to a licensed contractor is recorded.',
   ['Store in a room with a washable floor, ventilation, a lock and a warning sign.',
    'Keep storage within the maximum time and temperature set by the rules and the competent authority.',
    'Check that the contractor holds a valid licence before first handover.',
    'Sign a handover record each time: date, class, weight, container count, names.'],
   'Weekly handover: 140 kg infectious in 20 boxes of 7 kg. A log entry records 140 kg, 20 boxes, driver, vehicle and licence number. Any later mismatch of more than 5 percent triggers a check.',
   'Audit a storage room with a 15-point checklist.',
   'Every point is scored with evidence and failures have actions and dates.'),
  ('Waste quantity and cost', 'Analyse', 3,
   'You cannot manage what you do not measure. Weekly weights show where to cut waste.',
   ['Weigh each class weekly with a calibrated scale.',
    'Compute kg per bed-day or kg per patient visit.',
    'Compare classes and find the largest source.',
    'Estimate savings from better sorting and fewer disposables.'],
   '20 beds, 75 percent occupancy = 15 bed-days per day. Waste 45 kg per day gives 3.0 kg per bed-day. Cutting infectious share from 25 to 15 percent saves 4.5 kg per day, 1,642 kg per year.',
   'Work out kg per bed-day and a reduction target.',
   'Arithmetic is correct and the source of waste named.'),
  ('Infection control and injury response', 'Apply', 3,
   'A needle-stick or spill needs an immediate, practised response.',
   ['Wash the wound with soap and water, do not squeeze, report at once.',
    'For a spill: restrict the area, wear protection, absorb, disinfect, bag, record.',
    'Keep post-exposure contacts and steps on a laminated card.',
    'Train and vaccinate staff as medical advice and the rules require.'],
   'A 100 mL blood spill needs about 500 mL of disinfectant at the label strength and a contact time stated on the label, typically 10 minutes. Record time, person and area.',
   'Write a one-page response card and test it in a drill.',
   'Drill completed in under 5 minutes and card reviewed by a clinician.'),
  ('Treatment, disposal and the licensed chain', 'Understand', 3,
   'Different classes go to different treatment: disinfection, incineration or special handling. Each step needs licensed operators.',
   ['Explain the options in general terms: steam sterilisation, chemical disinfection, incineration.',
    'Explain why on-site treatment equipment needs approval and monitoring.',
    'Keep copies of the contractor licence and disposal certificates.',
    'Never burn, bury or dump waste.'],
   'A contractor collects 600 kg per month. Certificates must match: 600 kg collected equals 600 kg received. A shortfall of 30 kg (5 percent) must be explained in writing.',
   'Build a chain-of-custody diagram from the bin to final disposal.',
   'Every step has a responsible party and a record.'),
  ('Management plan, training and audit', 'Create', 4,
   'A plan makes safe waste handling routine. It names owners, rules, training and checks.',
   ['Name a responsible person and a deputy.',
    'Write procedures in plain words and train every new staff member before first duty.',
    'Audit monthly and report results to management.',
    'Review after any incident and update the plan.'],
   'Training 24 staff for 1.5 hours each is 36 staff hours. At 300 RUB per hour internal cost, this is 10,800 RUB a year, small beside one injury claim.',
   'Draft the plan with roles, training schedule and audit calendar.',
   'Plan names owners, dates and records and passes mentor review.'),
 ],
 quiz=[
  ('Why sort waste where it is made?', 'It is safest, cheapest and avoids turning general waste into hazardous waste.'),
  ('How full may a sharps box be?', 'Up to the fill line, usually about three quarters, then close it.'),
  ('Should needles be recapped?', 'No; drop the whole device in a puncture-proof box.'),
  ('What does a handover record contain?', 'Date, class, weight, containers, names and licence details.'),
  ('Who may transport hazardous medical waste?', 'Only a licensed contractor, as set by the relevant federal rules and the competent authority; clinic staff and learners do not carry it off site.'),
  ('A clinic makes 3 kg waste per bed-day with 15 bed-days a day. Daily total?', '3 x 15 = 45 kg per day, which is 315 kg per week; this is the baseline against which any reduction target is set.'),
  ('First action after a needle-stick?', 'Wash the wound with soap and water without squeezing, report at once, record the time and seek medical help using the post-exposure card.'),
  ('May waste be burned on site informally?', 'No; treatment needs approved equipment, monitoring and licences, and burning, burying or dumping waste is never allowed.'),
  ('Why weigh waste weekly?', 'To track trends and costs, find the largest source and show whether sorting changes actually reduce volume, for example kg per bed-day.'),
  ('What shows a contractor is legitimate?', 'A valid licence, checked and filed before first handover, plus disposal certificates whose weights match the handover log.'),
 ],
 rubric=[
  ('Classification', 'Fewer than 25 of 30 correct.', 'At least 28 of 30 correct with reasons.', 'All correct and notes edge cases.'),
  ('Storage and handover', 'No records.', 'Checklist complete and records tied to each handover.', 'Also finds and fixes a mismatch.'),
  ('Quantity analysis', 'Arithmetic errors.', 'Correct kg per bed-day and a target.', 'Also costs the reduction.'),
  ('Injury response', 'No card.', 'Card tested in a drill under 5 minutes.', 'Also includes reporting and follow-up.'),
  ('Compliance', 'Ignores licensing.', 'Names licence checks and the competent authority.', 'Also keeps a certificate file and audit calendar.'),
 ],
 ladder=[
  'L1 Basic: Name the waste groups and the main danger of sharps, and state the first action after a needle-stick (awareness only).',
  'L2 Awareness: Explain why waste is separated at the point of use, what mixing costs and why only licensed contractors may carry hazardous classes.',
  'L3 Foundation: Sort items into the correct class and fill containers to the line, labelling each with date, room and waste class.',
  'L4 Practitioner: Build a plan with records, drills and a handover log, and calculate kg per bed-day with a reduction target.',
  'L5 Specialist: Audit a facility against a checklist, find mismatches in handover records and lead staff training under the responsible person.',
  'L6 Advanced: Design waste systems across several sites with licensed partners, shared records and a common audit calendar.',
  'L7 Super expert: Lead policy and infection-safe waste chains (needs formal qualifications).',
 ],
 jobs=[
  ('Waste handling assistant', 'Sorts and moves waste under a supervisor.'),
  ('Clinic hygiene coordinator', 'Runs bins, training and records.'),
  ('Compliance clerk', 'Keeps licences, certificates and logs.'),
  ('Facility manager assistant', 'Audits storage and contractors.'),
  ('Infection control assistant', 'Supports drills and incident reviews.'),
 ],
 next='Next courses: Nursing Care Support, Occupational Health and Safety, and Environmental Management.',
))

COURSES.append(dict(
 id='RU-28', title='Mobile App Services', level='L4 Practitioner',
 summary='Learn to plan, build the case for, test and run a mobile app service: user needs, a minimum product, data handling, store rules, analytics and support. You work through a small booking app.',
 outcomes=[
  ('Understand', 'Explain the stages of an app project and the roles in a small team.'),
  ('Apply', 'Write user stories and acceptance tests for a core flow.'),
  ('Analyse', 'Break monthly running cost and user retention into parts and find the weakest step.'),
  ('Evaluate', 'Judge a data and privacy plan against the relevant federal rules and store policies.'),
  ('Create', 'Build a release plan, a test log and a support process for version 1.0.'),
 ],
 task='Produce a product brief, 12 user stories with tests, a release checklist, a privacy note and a retention analysis for a small booking app.',
 condition='Given a business idea, a spreadsheet, a free prototype tool and 6 hours of working time, with a mentor to review.',
 standard='Stories are testable, release checklist has at least 20 items, retention arithmetic is correct, every personal data item has a purpose, and at least 8 of 10 check answers are right.',
 who='Founders, product assistants, junior developers, designers and small business owners.',
 req='Basic arithmetic, a spreadsheet and a device with a browser. No coding is needed to study.',
 safety='Apps collect personal data, take payments and are published through stores with their own rules. Data protection, data localisation, payment, consumer and advertising rules are set by the relevant federal rules and the competent authority. This course gives no legal advice. Check with the competent Russian authority and a local adviser, especially for health, finance or child users. Do not promise users results the app cannot deliver.',
 evidence='Evidence products: product brief, user stories with tests, prototype, release checklist, privacy note, retention analysis and support playbook.',
 modules=[
  ('Problem, user and product brief', 'Understand', 3,
   'An app succeeds when it solves one problem for a named user better than their current way.',
   ['State the user, the problem and the current workaround in three sentences.',
    'Interview five users and record exact words, not opinions about features.',
    'Define the single main job the app must do.',
    'Set a measurable goal such as 100 bookings in the first 60 days.'],
   'A salon owner takes 40 bookings a week by phone and loses about 6 to missed calls. An app that captures even 4 of those gives 4 x 52 = 208 extra bookings a year; at 1,500 RUB each, 312,000 RUB a year of revenue.',
   'Write the brief and interview notes for the booking app.',
   'Brief names user, problem, workaround and a number to reach.'),
  ('User stories and acceptance tests', 'Apply', 4,
   'A story states who, what and why. A test says how to know it is done.',
   ['Write stories as: As a customer I want to book a slot so that I do not phone.',
    'Add acceptance tests with clear pass or fail.',
    'Split stories larger than 3 days of work.',
    'Rank stories: must, should, could for version 1.0.'],
   'Story: book a slot. Test: choose service, date, time; see confirmation within 3 seconds; a message arrives within 1 minute; a slot already taken cannot be booked twice.',
   'Write 12 stories with tests and rank them.',
   'Every must-story has a clear, testable pass condition.'),
  ('Design, prototype and usability', 'Create', 4,
   'A prototype tests the idea before expensive code. Five test users find most big problems.',
   ['Sketch screens for the main flow with no more than 4 taps to book.',
    'Use a clear tap size of at least 44 pixels and readable text.',
    'Test a clickable prototype with five users and record where they stop.',
    'Fix the top three problems before building.'],
   'Five tests: 4 of 5 users fail to find the date picker. One fix (a bigger button) is applied and the next test passes at 5 of 5.',
   'Build a prototype and run five tests.',
   'Test log shows time to finish, errors and three fixes.'),
  ('Build choices, quality and testing', 'Evaluate', 4,
   'Native, cross-platform or web app: each trades cost, speed and quality. Testing must cover devices, networks and edge cases.',
   ['Compare options by cost, time to market, performance and skills.',
    'Test on at least three screen sizes and two OS versions.',
    'Test with slow or lost connection and with interrupted calls.',
    'Track defects by severity and fix all blockers before release.'],
   'Cross-platform build 10 weeks at two developers; native on two systems 18 weeks. For a simple booking app the saving of 8 weeks is worth more than a small speed gain.',
   'Choose a build approach and justify it with a table.',
   'Choice is argued with numbers and risks.'),
  ('Data, privacy and store rules', 'Evaluate', 4,
   'Collect only what you need and tell users why. Store rules are checked before every release.',
   ['List each data item, its purpose, who sees it and how long it is kept.',
    'Ask consent in plain words and let users delete their data.',
    'Check store policies on payments, content and permissions.',
    'Know that personal data rules, including where data is stored, come from the relevant federal rules and the competent authority.'],
   'The app asks for name, phone and email. Location is not needed for booking, so it is not collected. Removing one unneeded item cuts risk and the number of consent screens by one.',
   'Write a privacy note with a data table.',
   'Every item has a purpose and retention time; no unneeded permission.'),
  ('Launch, analytics and growth', 'Analyse', 4,
   'Launch is the start of learning. Measure activation and retention, not downloads.',
   ['Define activation, for example first booking within 7 days.',
    'Compute retention at day 1, day 7 and day 30.',
    'Track cost per install and cost per booking.',
    'Run one change at a time and compare.'],
   'Of 1,000 installs, 400 activate (40 percent). Day-30 retention is 120 users = 12 percent of installs. If spend is 50,000 RUB, cost per active user is 50,000 / 400 = 125 RUB.',
   'Calculate the funnel and find the weakest step.',
   'Correct percentages and a named improvement test.'),
  ('Running cost and support', 'Apply', 3,
   'A service has ongoing costs and users who need help.',
   ['List costs: hosting, store fees, messages, payment fees, support time and updates.',
    'Set a first-response time target, for example 4 working hours.',
    'Keep a defect and request log and review weekly.',
    'Plan updates for new OS versions.'],
   'Hosting 6,000 RUB, messages 4,000 RUB, tools 3,000 RUB, support 8 hours at 600 RUB = 4,800 RUB. Total 17,800 RUB a month. Each booking at 60 RUB margin needs 297 bookings to cover cost.',
   'Build a monthly cost table and a support playbook.',
   'Costs are complete; playbook has response targets.'),
  ('Release plan and review', 'Create', 3,
   'A release is a controlled event with checks, a rollback plan and a review.',
   ['Make a 20-item release checklist: tests, store listing, privacy, support, monitoring.',
    'Release to a small group first (staged rollout).',
    'Define rollback triggers, such as crash rate above 2 percent.',
    'Hold a review two weeks after launch.'],
   'Staged rollout to 10 percent of 2,000 users = 200. Crash rate 3 percent is above the 2 percent trigger, so release pauses and a fix is made.',
   'Write the release checklist and the review agenda.',
   'Checklist has 20 or more items with owners and a rollback trigger.'),
 ],
 quiz=[
  ('Why interview users before building?', 'To confirm a real problem exists and to hear exact words about the current workaround, which avoids spending weeks building features nobody asked for.'),
  ('Give an acceptance test for booking.', 'A booked slot shows confirmation within 3 seconds, a message arrives within 1 minute, and a second booking of the same slot is blocked.'),
  ('Why use a prototype?', 'To test the idea cheaply with five users before coding, because most big usability problems appear early and are far cheaper to fix on screen than in code.'),
  ('1,000 installs, 400 active: activation rate?', '400 / 1,000 = 40 percent; the rate shows how many installs reach the first booking, which matters more than the download count.'),
  ('Why collect minimal data?', 'It lowers breach risk, shortens consent screens and meets purpose-limitation duties, because every item held needs a stated purpose, an owner and a retention time.'),
  ('What is a staged rollout?', 'Releasing to a small share of users first, for example 10 percent, to catch crashes and defects before the whole audience is affected.'),
  ('Name a rollback trigger.', 'A crash rate above a set limit such as 2 percent; when it is passed, the release pauses, the cause is fixed and the plan is reviewed.'),
  ('Who sets personal data rules?', 'The relevant federal rules and the competent authority, including where data is stored; a local adviser should check the plan, as this course gives no legal advice.'),
  ('Why measure retention, not downloads?', 'Retention shows whether users find lasting value; downloads can be bought, but 12 percent still active at day 30 shows a product people return to.'),
  ('What do you record in a support log?', 'The request, the time received, severity, the fix applied and the user feedback, so weekly review can find repeated causes and measure the response time.'),
 ],
 rubric=[
  ('Product brief', 'Vague user.', 'Clear user, problem and number.', 'Also supported by interview quotes.'),
  ('Stories and tests', 'Stories untestable.', 'All must-stories have pass tests.', 'Also covers errors and edge cases.'),
  ('Privacy', 'Collects unneeded data.', 'Each item has purpose and retention.', 'Also maps to rule checks by an adviser.'),
  ('Analytics', 'Counts downloads only.', 'Funnel and retention correct.', 'Also tests one change.'),
  ('Release', 'No checklist.', '20 items, owners, rollback trigger.', 'Also includes staged rollout data.'),
 ],
 ladder=[
  'L1 Basic: Name what an app is, what personal data it may collect and why users must be told the purpose of each item.',
  'L2 Awareness: Explain the steps from idea to store release, including prototype, testing, privacy check, staged rollout and support.',
  'L3 Foundation: Write simple user stories with acceptance tests that have a clear pass or fail result and rank them by priority.',
  'L4 Practitioner: Plan, test and release a small app with a privacy note, a 20-item checklist, a funnel analysis and a support playbook.',
  'L5 Specialist: Lead product backlog, analytics and support for a live app, running one measured change at a time and reviewing results.',
  'L6 Advanced: Run several apps with architecture, security and growth plans, and review privacy duties with a local adviser before each release.',
  'L7 Super expert: Direct a product portfolio, set measurable goals for each app and mentor teams on testing, support and responsible data use.',
 ],
 jobs=[
  ('Product assistant', 'Writes stories and keeps the backlog.'),
  ('QA tester', 'Runs test cases on several devices and networks, logs defects by severity and confirms fixes before release.'),
  ('App support agent', 'Answers user requests within the response target, tracks issues in a log and reports repeated causes weekly.'),
  ('Junior mobile developer', 'Builds screens with a senior lead.'),
  ('Digital product owner', 'Owns a small app and its results.'),
 ],
 next='Next courses: Web Design and Development, Digital Marketing, and Data Privacy Basics.',
))

COURSES.append(dict(
 id='RU-29', title='Social Media Marketing', level='L4 Practitioner',
 summary='Learn to plan, produce, publish and measure social media marketing for a small business: audience, content calendar, paid reach basics, community replies and honest reporting.',
 outcomes=[
  ('Understand', 'Explain how audience, message and channel fit together in a small business plan.'),
  ('Apply', 'Build a four-week content calendar with formats, goals and posting times.'),
  ('Analyse', 'Calculate engagement rate, cost per click and cost per lead and find the weakest step.'),
  ('Evaluate', 'Judge posts and advertisements against honesty, consent and platform rules.'),
  ('Create', 'Build a monthly report with findings and the next test.'),
 ],
 task='Produce an audience profile, a four-week calendar of 16 posts, one small paid test plan, a reply guide and a monthly report for a local small business.',
 condition='Given a business profile, a spreadsheet, free design tools and 6 hours of working time, with a mentor to review.',
 standard='Calendar covers all four weeks with a goal for every post, metric arithmetic is correct, every claim can be backed up, and at least 8 of 10 check answers are right.',
 who='Small business owners, marketing assistants, freelancers and community managers.',
 req='Basic arithmetic, a spreadsheet and access to the platforms the business uses.',
 safety='Advertising, consumer protection, personal data, labelling of ads and platform terms are set by the relevant federal rules and the competent authority, and platform access and rules can change. Check with the competent Russian authority and a local adviser, especially for regulated goods, health claims, finance and children. Never buy fake followers, invent reviews or promise guaranteed results. Reach and sales vary and this course promises none.',
 evidence='Evidence products: audience profile, content calendar, paid test plan, reply guide, monthly report.',
 modules=[
  ('Goals, audience and message', 'Understand', 3,
   'Marketing starts with a goal and a person, not a platform.',
   ['Set one goal with a number and a date, for example 30 enquiries in 8 weeks.',
    'Describe the audience by need, place, age range and where they spend time.',
    'Write a one-sentence promise that is true and checkable.',
    'Choose one or two channels, not all of them.'],
   'A bakery wants 30 enquiries for custom cakes in 8 weeks. Audience: parents aged 28 to 45 within 8 km who plan birthdays. Promise: cakes made to order with 48 hours notice. Step 1: 30 / 8 = 3.75, so about 4 enquiries a week. Step 2: the last three weeks gave 2, 3 and 2, a pace of 7 / 3 = 2.3 a week. Step 3: the plan needs nearly double the effort, so adjust posts or channel.',
   'Write goal, audience and promise for a local business, then compute the weekly pace needed and compare it with the recent pace in a short note.',
   'Goal has a number and date; promise can be checked; weekly pace is computed correctly and compared with past results in at least one sentence.'),
  ('Content planning and calendar', 'Apply', 4,
   'A calendar keeps posting steady and links each post to a goal.',
   ['Mix content: useful, proof, behind the scenes and offer, for example 40/20/20/20.',
    'Plan 3 to 4 posts a week and the format of each: photo, short video, text, story.',
    'Reuse one idea in several formats.',
    'Batch production: make a week of content in one session.'],
   '16 posts in 4 weeks: 6 useful, 4 proof, 3 behind the scenes, 3 offers, and 6 + 4 + 3 + 3 = 16. That is 4 posts a week. A batch session of 3 hours (180 minutes) for 4 posts is 45 minutes each, so 16 posts take 16 x 45 = 720 minutes, or 12 hours. If each idea is reused in 2 formats, 16 posts need only 8 ideas. Check: every post has a goal and a date.',
   'Build the four-week calendar with goal per post, a format for each, a batch session plan and the total production hours worked out.',
   'All 16 posts have format, goal and date; the mix adds to 16; production hours are computed correctly and shown against the time available.'),
  ('Creating clear, honest content', 'Create', 4,
   'Good posts are clear, specific and true.',
   ['Lead with the point in the first line.',
    'Use real photos and plain words; add a single call to action.',
    'Add captions to videos and alt text to images.',
    'Mark paid or sponsored posts as the rules require; never fake reviews.'],
   'Weak: Best cakes in town. Strong: Birthday cakes for 10 to 12 people, ready in 48 hours, from 2,400 RUB. One claim, one number, one action. Check the number: a cake for 12 people at 2,400 RUB is 2,400 / 12 = 200 RUB a portion. Check the promise: 48 hours must match what the kitchen can really bake. Check the action: one line such as message us to order. Remove any word you cannot prove.',
   'Write six captions and a call to action for each, add alt text for every image, and mark each claim with the proof that supports it.',
   'Each caption has one point, one action and no unsupported claim; all six images have alt text; every number can be traced to a price list or record.'),
  ('Community and replies', 'Apply', 3,
   'Replies build trust. Slow or rude replies lose customers.',
   ['Set a reply target, for example within 4 working hours.',
    'Write short reply templates for price, delivery and complaints.',
    'Move private details to a private message.',
    'Handle criticism calmly and fix the real problem.'],
   'Over a week 40 comments and 12 messages arrive. At 3 minutes each, replies take 52 x 3 = 156 minutes, about 2.6 hours. Templates cut it by about a third: 156 / 3 = 52 minutes saved, leaving 104 minutes, about 1.7 hours. Check the target: replies in two fixed slots a day meet a 4-hour goal only if the slots are no more than 4 hours apart.',
   'Write a reply guide with five templates for price, delivery, complaint, thanks and a request that moves to private message, and time one reply cycle.',
   'Templates are polite, accurate and avoid private data in public; each has a reply target; the weekly time estimate is computed correctly from message counts.'),
  ('Metrics and analysis', 'Analyse', 4,
   'Numbers show what works. Choose a few that tie to the goal.',
   ['Engagement rate = (likes + comments + shares) / reach x 100.',
    'Click-through rate = clicks / views x 100.',
    'Cost per lead = spend / leads.',
    'Compare against your own past results, not other accounts.'],
   'A post reaches 2,000 people with 90 reactions: 90 / 2,000 x 100 = 4.5 percent. A small paid test of 3,000 RUB gets 1,500 views, 45 clicks (45 / 1,500 = 3.0 percent) and 6 leads: 3,000 / 6 = 500 RUB per lead. Cost per click is 3,000 / 45 = 66.7 RUB. Only 6 / 45 = 13.3 percent of clicks became leads, so the weakest step is after the click: improve the landing message.',
   'Compute four metrics from a given table, name the weakest step in the chain from view to lead, and write one sentence on what to change first.',
   'All arithmetic is correct to one decimal place; the weak step is found with the figure that proves it; the proposed change tests one variable only.'),
  ('Paid reach basics', 'Apply', 4,
   'A small paid test can show which message works. It must be capped and measured.',
   ['Set a budget cap per day and per test.',
    'Test one variable at a time: image, line or audience.',
    'Wait for enough results before choosing, for example 100 clicks per version.',
    'Follow ad labelling and platform rules, and check restrictions with the competent authority.'],
   'Two versions each get 1,500 RUB, 3,000 RUB in all. A: 3,000 views, 60 clicks (2.0 percent, 25 RUB per click), 4 leads = 1,500 / 4 = 375 RUB per lead. B: 3,000 views, 36 clicks (1.2 percent, 41.7 RUB per click), 3 leads = 1,500 / 3 = 500 RUB per lead. A wins, but with so few leads and under 100 clicks per version, repeat the test before scaling spend.',
   'Plan a two-version test with a budget cap, one changed variable, a run length and a written decision rule stated before the test starts.',
   'Test changes one variable, caps spend per day and in total, states the decision rule in numbers, and notes the platform rules and labelling to follow.'),
  ('Ethics, rules and risk', 'Evaluate', 3,
   'Trust is the main asset. Rules protect users and your business.',
   ['Get consent before posting photos of people, especially children.',
    'Do not collect or share personal data without a lawful basis under the relevant federal rules.',
    'Disclose paid partnerships and never mislead about price or results.',
    'Plan for a crisis: pause posts, check facts, reply once, correct openly.'],
   'A post says 50 percent off but the base price rose 40 percent a week earlier. Old price 1,000 RUB, raised to 1,400 RUB, then halved to 700 RUB. Against the earlier 1,000 RUB the saving is 300 RUB, 30 percent, not 50. The post is misleading and must be corrected with the true figure. Check each claim against a price record, and each photo of a person for written consent.',
   'Audit six posts against a checklist covering claims, price, consent, labelling and personal data, then rewrite every post that fails.',
   'All misleading or unconsented items are found and rewritten; each fix names the rule or record behind it; the discount arithmetic is correct.'),
  ('Monthly report and next test', 'Create', 3,
   'A report turns numbers into one decision.',
   ['Show goal, result, and the three metrics that matter.',
    'Explain why, using evidence from posts.',
    'Name one test for next month with a hypothesis.',
    'Keep the report to one page.'],
   'Goal 30 enquiries; result 24, and 24 / 30 = 80 percent, a gap of 6. The pace was 24 / 8 = 3 a week against 3.75 needed. Best post type: proof posts with 6.1 percent engagement. Hypothesis: more proof posts raise enquiries. Next test: double the proof posts from 4 to 8 and compare enquiries with this month.',
   'Write a one-page report from a given data table with goal, result, three metrics, the reason and one test for next month with a hypothesis.',
   'Report fits one page, has goal, result, reason and one test; percentages are computed correctly; every reason points to a named post or number.'),
 ],
 quiz=[
  ('Why start with a goal, not a platform?', 'The goal decides the audience, the message and the channel, so choosing a platform first risks effort spent where the right people are not.'),
  ('Engagement rate formula?', '(Likes + comments + shares) divided by reach, times 100; for 90 reactions on a reach of 2,000 it is 4.5 percent.'),
  ('3,000 RUB spend, 6 leads: cost per lead?', '3,000 divided by 6 is 500 RUB per lead; compare it with your own earlier tests, not with other accounts.'),
  ('Why change one variable in a test?', 'So you know which change caused the difference; if image and line both change you cannot tell which one worked.'),
  ('Should you buy followers?', 'No; bought followers are not real customers, distort every metric and break platform rules, so the account may be penalised.'),
  ('What is a good reply target?', 'A set time such as within 4 working hours, written down, checked weekly and backed by templates so the team can keep it.'),
  ('Why disclose paid posts?', 'Honesty and the advertising rules require it, and readers who find a hidden paid post stop trusting the business.'),
  ('A 50 percent off claim but price rose first. Problem?', 'It is misleading; if 1,000 RUB rose to 1,400 RUB and then halved, the real discount is 30 percent, so correct the post.'),
  ('Why batch content?', 'It saves setup time, such as 45 minutes a post in a 3-hour session, and keeps posting steady when the week gets busy.'),
  ('Why consent for photos of people?', 'They are personal data and children need special care, so get clear permission before posting and remove the photo on request.'),
 ],
 rubric=[
  ('Goal and audience', 'No number.', 'Number, date and clear audience.', 'Also supported by interviews.'),
  ('Calendar', 'Posts without goals.', 'Four weeks with goals and formats.', 'Also reuses ideas across formats.'),
  ('Metrics', 'Likes only.', 'Correct rates and cost per lead.', 'Also compares months.'),
  ('Honesty and rules', 'Unsupported claims.', 'All claims backed up; ads labelled.', 'Also has a crisis plan.'),
  ('Reporting', 'List of numbers.', 'One page with a reason and test.', 'Also quantifies the expected effect.'),
 ],
 ladder=[
  'L1 Basic: Name common platforms and what a post, reach and engagement mean.',
  'L2 Awareness: Explain why a goal and audience come first.',
  'L3 Foundation: Write clear posts and a simple calendar.',
  'L4 Practitioner: Plan, run and report a month of marketing for a small business.',
  'L5 Specialist: Lead paid tests, community teams and multi-channel plans.',
  'L6 Advanced: Design brand-level strategy and attribution models.',
  'L7 Super expert: Direct marketing for many brands and mentor leaders.',
 ],
 jobs=[
  ('Social media assistant', 'Schedules posts and replies to comments.'),
  ('Content creator', 'Makes photos, short videos and captions.'),
  ('Community manager', 'Builds and moderates an audience.'),
  ('Paid media assistant', 'Sets up and watches small ad tests.'),
  ('Marketing analyst assistant', 'Builds the monthly report.'),
 ],
 next='Next courses: Digital Marketing, Graphic Design, and Mobile App Services.',
))

COURSES.append(dict(
 id='RU-30', title='Automobile (Sales, Service, Workshop)', level='L4 Practitioner',
 summary='Learn how a car dealership and workshop run: vehicle sales steps, service intake, job cards, labour and parts pricing, workshop safety, quality checks and customer records.',
 outcomes=[
  ('Understand', 'Explain the flow of a vehicle from sale to delivery and from service intake to hand-back.'),
  ('Apply', 'Prepare a quote with vehicle price, extras and financing figures, and a job card with labour and parts.'),
  ('Analyse', 'Calculate workshop efficiency, gross margin and parts turnover and find weak points.'),
  ('Evaluate', 'Judge a workshop against safety, environmental and warranty checks.'),
  ('Create', 'Build a service process with checklists, records and customer follow-up.'),
 ],
 task='Prepare a sales quote, a service intake form, two job cards, a workshop safety checklist and a weekly performance sheet for a small dealership with a workshop.',
 condition='Given price lists in RUB, a labour rate, a spreadsheet and 6 hours of working time, with a mentor to review.',
 standard='Quotes and job cards have no arithmetic error, every safety checklist item has a record, efficiency and margin are correctly calculated, and at least 8 of 10 check answers are right.',
 who='Sales trainees, service advisers, workshop assistants, parts clerks and small garage owners.',
 req='Basic arithmetic, a spreadsheet and interest in vehicles. No licence is needed to study.',
 safety='Vehicle sale, registration, safety inspection, warranty, consumer protection, waste oils and batteries, and dealer and repair licensing are governed by the relevant federal rules and the competent authority. Workshop work involves lifting, fire, fumes, electrics (including high-voltage systems) and moving parts. Only trained persons may carry out safety-critical repairs such as brakes and steering. Check with the competent Russian authority and a local adviser. Do not certify a vehicle as safe without proper inspection.',
 evidence='Evidence products: sales quote, intake form, job cards, safety checklist, margin calculation and weekly sheet.',
 modules=[
  ('Dealership and workshop flow', 'Understand', 3,
   'A dealership has sales, finance, service, parts and bodywork. They share customers and records.',
   ['Name the departments and what each earns.',
    'Trace a sale: enquiry, test drive, quote, contract, payment, registration, handover.',
    'Trace a service: booking, intake, inspection, quote, approval, repair, quality check, hand-back.',
    'Explain why records and customer approval protect both sides.'],
   'A small site sells 20 cars and does 160 service jobs a month. If a typical car sale gives 90,000 RUB gross and a service job 4,000 RUB, service gives 160 x 4,000 = 640,000 RUB and sales give 20 x 90,000 = 1,800,000 RUB, so service is 640,000 / 2,440,000 = 26 percent of total gross and sales are 74 percent. Over 22 working days 160 jobs is about 7 jobs a day. Check: 640,000 + 1,800,000 = 2,440,000. Both departments need customer records, so one missing signature hurts both.',
   'Draw both flows, mark where signatures and customer approvals are needed, and compute the share of gross from service for the figures given.',
   'All steps are in order and each has a record; at least 4 signature points are marked; the service share is computed correctly.'),
  ('Sales conversation and needs analysis', 'Apply', 4,
   'Good selling starts with questions about use, budget and trade-in.',
   ['Ask about use: daily distance, passengers, parking, budget.',
    'Match two or three vehicles to needs and explain the differences.',
    'Run a test drive with a checklist.',
    'Be honest about condition, history and limits.'],
   'A customer drives 60 km a day, five days a week. 60 x 5 x 48 weeks = 14,400 km a year. At 8 L/100 km and fuel 55 RUB per L, fuel is 14,400 x 0.08 x 55 = 63,360 RUB a year. A second car at 5.5 L/100 km uses 14,400 x 0.055 = 792 L, costing 792 x 55 = 43,560 RUB, so it saves 63,360 - 43,560 = 19,800 RUB a year. Use such figures to compare two options honestly.',
   'Role-play a needs interview and record the answers, then match two options and compare their yearly fuel cost with the arithmetic shown.',
   'Needs are recorded, two options matched, facts stated accurately, and the fuel comparison is correct with distance, consumption and price all written down.'),
  ('Quotes, trade-in and finance arithmetic', 'Apply', 4,
   'A quote must show the full price and all extras clearly.',
   ['List base price, options, delivery, registration and insurance separately.',
    'Value a trade-in using condition and market checks, and explain the figure.',
    'Compute a simple loan payment and total cost of credit.',
    'Show the total to pay and the monthly amount.'],
   'Car 1,500,000 RUB, options 80,000 RUB, trade-in 400,000 RUB: to pay 1,180,000 RUB. Loan of 800,000 RUB over 36 months with total interest 190,000 RUB: total repaid 990,000 RUB, about 27,500 RUB a month (990,000 / 36). The credit costs 190,000 RUB, 23.75 percent of the loan. The customer also pays the rest in cash: 1,180,000 - 800,000 = 380,000 RUB. Show cash, loan, interest and monthly amount on separate lines.',
   'Prepare a quote with a trade-in and a loan scenario, listing price, options, trade-in, cash needed, total repaid and monthly payment.',
   'All lines add up; total cost of credit shown plainly in RUB; the trade-in figure has a stated basis; the customer can read the total to pay in one place.'),
  ('Service intake and diagnosis', 'Apply', 4,
   'The job card starts with the customer\'s words and a careful check of the car.',
   ['Record mileage, fuel level, damage and warning lights with photos.',
    'Write the customer complaint in their words.',
    'Follow a diagnostic path: check, test, confirm, then quote.',
    'Get written approval before extra work.'],
   'Complaint: squeal when braking. Check: front pads 2 mm (limit 3 mm). Quote: pads 3,200 RUB plus labour 1.0 h at 2,000 RUB = 5,200 RUB. Approval recorded before work. If the technician then finds worn discs needing 6,500 RUB of parts and 1.5 h of labour (3,000 RUB), that adds 9,500 RUB and the new total is 14,700 RUB, so work stops until the customer approves again in writing.',
   'Complete two job cards from case notes, each with complaint, mileage, findings, quote, approval and a second approval for one extra item.',
   'Complaint, findings, quote and approval are all recorded; extra work has its own written approval; quote arithmetic has no error.'),
  ('Labour, parts and workshop efficiency', 'Analyse', 4,
   'Workshops earn from labour hours sold and parts margin. Efficiency measures how well time is used.',
   ['Efficiency = hours sold / hours worked.',
    'Utilisation = hours worked / hours available.',
    'Parts margin = (sell price - cost) / sell price.',
    'Turnover of stock = yearly parts cost / average stock value.'],
   'A technician is present 40 h, works 34 h on jobs and sells 38 h of flat-rate time. Utilisation = 85 percent; efficiency = 38 / 34 = 112 percent; productivity = 38 / 40 = 95 percent. For parts: sell 5,000 RUB, cost 3,500 RUB, margin = 1,500 / 5,000 = 30 percent. Stock turnover: yearly parts cost 2,400,000 RUB / average stock 600,000 RUB = 4 turns a year, so stock lasts about 3 months.',
   'Calculate four measures from a weekly table, explain in one line what each tells a manager, and name one improvement with the figure it targets.',
   'All measures correct to the nearest percent; each is tied to a decision; one improvement is named with the figure it should change.'),
  ('Workshop safety and environment', 'Evaluate', 4,
   'Workshops have lifting, fire, chemical and electrical risks, and waste that must be handled correctly.',
   ['Check lifts and stands before use and mark the load limit.',
    'Keep fire extinguishers, spill kits and clear exits.',
    'Store oils, coolants, batteries and filters for licensed collection.',
    'Only trained persons work on high-voltage vehicles.'],
   'A lift rated 3,500 kg is used for a van of 3,200 kg plus 400 kg of load. Total 3,600 kg exceeds the rating by 100 kg, so the job must not proceed on that lift. Check: the lift has 3,500 - 3,200 = 300 kg of spare capacity, but the load is 400 kg. Move the job to a lift rated higher, or remove the load first. Record the decision and tell the supervisor.',
   'Audit a workshop with a 20-point checklist covering lifts, fire, fumes, electrics and waste, and write an action for every failed item.',
   'All failures have an action, owner and date; at least 18 of 20 points are checked with a record; no job is allowed above a rated load.'),
  ('Quality, warranty and complaints', 'Evaluate', 3,
   'A final check catches errors. Warranty and complaints need records and fairness.',
   ['Do a road test and a final checklist with sign-off.',
    'Return old parts on request and explain the work.',
    'Record warranty claims with date, mileage and findings.',
    'Handle complaints with facts, a clear timeline and consumer rules from the competent authority.'],
   'Out of 160 jobs a month, 8 come back within 14 days. Comeback rate = 5 percent. Target 2 percent, which is about 3 jobs, so 5 extra jobs per month need root-cause review. Cost check: 8 free repeat jobs at 4,000 RUB is 32,000 RUB of lost work; at the target of 3 it would be 12,000 RUB, so about 20,000 RUB a month is avoidable. Trace each comeback to intake, diagnosis, parts or the final check.',
   'Calculate comeback rate, work out the cost of repeat jobs, and write a root-cause note that traces each case to one process step.',
   'Rate and cost are correct; the cause is traced to a step; one corrective action has an owner and a date.'),
  ('Customer records and follow-up', 'Create', 3,
   'A good record helps the next visit and keeps customers.',
   ['Record vehicle, history, next service date and consent for contact.',
    'Send a reminder at the due date.',
    'Ask for feedback after a visit.',
    'Protect personal data according to the relevant federal rules.'],
   'Of 500 customers, a reminder campaign brings back 90 (18 percent). At 4,000 RUB per job, 90 jobs give 360,000 RUB of work, which is 720 RUB of work per customer contacted (360,000 / 500). Only customers who gave consent may be contacted, so check the record before sending any reminder.',
   'Design a reminder process and a feedback form, with the consent check, the timing of each message and the measure of return rate.',
   'Process has consent, timing and a measure; the return rate is computed correctly; the form has at most 5 questions and no unneeded personal data.'),
 ],
 quiz=[
  ('What goes on a service job card?', 'Complaint in the customer words, mileage, findings, quote, written approval, work done and final sign-off, each with a date and a name.'),
  ('Why get approval before extra work?', 'It protects the customer from surprise bills and the workshop from disputes, because the agreed price and scope are written down.'),
  ('Efficiency formula?', 'Hours sold divided by hours worked; for 38 hours sold and 34 worked it is 112 percent, which shows time used well.'),
  ('Lift rated 3,500 kg, vehicle 3,600 kg. Use it?', 'No; the total exceeds the rating by 100 kg, so use a stronger lift or reduce the load and record the decision.'),
  ('Loan 800,000 RUB, interest 190,000 RUB: total repaid?', '800,000 plus 190,000 is 990,000 RUB, about 27,500 RUB a month over 36 months, and the customer must see this total.'),
  ('Who may work on high-voltage systems?', 'Only trained and authorised persons with the right tools and procedure; everyone else keeps clear and does not touch orange cables.'),
  ('Comeback rate meaning?', 'Share of jobs returning for the same fault soon after repair, such as 8 of 160 jobs, which is 5 percent, a signal to find the root cause.'),
  ('Why show total cost of credit?', 'Honesty and consumer rules require clear total costs, so the customer can compare offers and is not surprised by the interest paid.'),
  ('How to store used oil?', 'In labelled sealed containers kept away from drains and heat, then handed to a licensed collector, with the collection recorded.'),
  ('Why photograph the car at intake?', 'To record existing damage, mileage and warning lights, so any later dispute about who caused a mark can be settled with facts.'),
 ],
 rubric=[
  ('Quotes', 'Totals do not add up.', 'Lines add up with credit cost shown.', 'Also offers two options with comparison.'),
  ('Job cards', 'Missing approval.', 'Complaint to sign-off recorded.', 'Also notes parts returned and advice given.'),
  ('Workshop measures', 'Arithmetic errors.', 'Efficiency and margin correct.', 'Also proposes and tests an improvement.'),
  ('Safety', 'Checklist unfinished.', 'Checklist with actions and owners.', 'Also covers high-voltage and waste.'),
  ('Customer records', 'No consent noted.', 'Records with consent and reminders.', 'Also measures return rate.'),
 ],
 ladder=[
  'L1 Basic: Name the departments of a dealership and basic workshop hazards.',
  'L2 Awareness: Explain a sale and a service job from start to finish.',
  'L3 Foundation: Prepare a simple quote and job card.',
  'L4 Practitioner: Run quotes, job cards, safety checks and weekly figures.',
  'L5 Specialist: Manage a service lane or sales team with targets.',
  'L6 Advanced: Lead a site with budgets, warranty and quality systems.',
  'L7 Super expert: Direct multi-site operations (needs relevant qualifications).',
 ],
 jobs=[
  ('Sales trainee', 'Meets customers and prepares quotes.'),
  ('Service adviser', 'Books, checks in and quotes service work.'),
  ('Parts clerk', 'Orders, stocks and sells parts.'),
  ('Workshop assistant', 'Supports technicians and keeps the bay safe.'),
  ('Small garage owner', 'Runs a garage with trained staff.'),
 ],
 next='Next courses: Car Repair and Maintenance, Customer Service, and Occupational Health and Safety.',
))

COURSES.append(dict(
 id='RU-31', title='Nursing Care Support', level='L4 Practitioner',
 summary='Learn the care support tasks that help a nurse or carer look after people: observation, hygiene, mobility, nutrition, infection prevention, safe records and communication. The course teaches support skills, not nursing practice.',
 outcomes=[
  ('Understand', 'Explain the limits of a care support role and when to call a nurse or doctor.'),
  ('Apply', 'Measure and record pulse, breathing rate and temperature correctly.'),
  ('Analyse', 'Compare observations over time and spot a change that needs escalation.'),
  ('Evaluate', 'Judge a care routine for dignity, safety and infection control.'),
  ('Create', 'Build a daily care plan sheet and a handover note for a care worker.'),
 ],
 task='Prepare a daily care support sheet, an observation chart, a safe-moving plan, an infection-prevention checklist and a handover note for one person in a small care setting.',
 condition='Given a case description, a blank chart, a spreadsheet and 5 hours of working time, with a qualified mentor to review.',
 standard='All observations plotted correctly, every escalation trigger named, hand hygiene steps in order, and at least 8 of 10 check answers are right.',
 who='Care workers, family carers, volunteers and learners who may later train as nurses or nursing assistants.',
 req='Good health, basic arithmetic, willingness to work with people respectfully. No qualification is needed to study.',
 safety='Nursing and care are regulated. What a support worker may do, medication handling, injections, wound care, licensing of care facilities and professional qualification are set by the relevant federal rules and the competent authority. This course does not qualify anyone as a nurse and gives no medical advice. Never give medicines, diagnose or change treatment unless authorised and trained. In an emergency call the emergency services at once. Check with the competent Russian authority and a local adviser.',
 evidence='Evidence products: observation chart, care support sheet, safe-moving plan, infection checklist and handover note.',
 modules=[
  ('Role, limits and dignity', 'Understand', 3,
   'A support worker helps with daily living and watches for change. Knowing the limits protects the person and the worker.',
   ['List what is inside the role: help with washing, eating, moving, comfort and observation.',
    'List what is outside it: diagnosing, giving medicines or treatments without authority.',
    'Show respect: knock, explain, ask consent, keep privacy.',
    'Know whom to call: nurse in charge, doctor, emergency services.'],
   'A resident refuses a wash. Instead of forcing it, the worker offers a choice of time, records the refusal, and tells the nurse. Respect and record, never force. Steps: stay calm, offer a later time, check the person is comfortable, write the refusal with the time, and tell the nurse before the shift ends. In a sort of 20 tasks, 9 may be inside the role, 6 need asking first and 5 are outside, and 9 + 6 + 5 = 20.',
   'Sort 20 tasks into inside role, ask first, and outside role, and give a one-line reason for each, naming whom to ask where needed.',
   'At least 19 of 20 sorted correctly with reasons; every ask-first task names the person to ask; no task outside the role is carried out.'),
  ('Observation and measurement', 'Apply', 4,
   'Pulse, breathing and temperature are early signs. Accurate measuring and recording matter.',
   ['Count pulse for 30 seconds and double it, or for 60 seconds if irregular.',
    'Count breathing for 60 seconds without telling the person.',
    'Take temperature with a clean device and record the site.',
    'Record time, value and your name on the chart.'],
   'Pulse counted 36 in 30 seconds = 72 per minute. Breathing 15 per minute. Temperature 36.8 C. All within common adult ranges; a temperature of 38.5 C must be reported at once. If the pulse feels irregular, count a full 60 seconds: 74 beats is 74 per minute with no doubling. If the mentor counts 70 and you count 72, the difference is 2, within the allowed 4. Write time, values, site and your name.',
   'Take and chart a full set of observations on a partner, with pulse, breathing and temperature, and compare your counts with the mentor reading.',
   'Counts are within 4 of the mentor reading and chart is complete with time, site, values and name; any abnormal value is reported at once.'),
  ('Hygiene, skin and comfort', 'Apply', 4,
   'Washing, mouth care and skin checks prevent infection and sores.',
   ['Prepare everything before starting; keep the person covered.',
    'Wash from clean to dirty areas and dry well, especially skin folds.',
    'Check skin for redness over bony places and report it.',
    'Change position at the interval set in the care plan.'],
   'A care plan says reposition every 2 hours: 12 changes in 24 hours. A missed night change leaves 4 hours on one side, which raises pressure sore risk, so it is reported. Check the plan: 24 / 2 = 12 changes, for example at 00:00, 02:00, 04:00 and so on to 22:00. Each entry records the time, the new position, skin condition and the signature. If two changes are missed, that is 2 of 12, about 17 percent of the day, and the gap is told to the nurse.',
   'Write a repositioning chart for a day and night with 12 entries, a skin check note and a place for a signature at every change.',
   'Times are even at 2-hour steps and each entry is signed; skin redness is flagged; any missed change is recorded with the reason.'),
  ('Safe moving and falls prevention', 'Apply', 4,
   'Poor lifting injures workers and patients. Use aids and follow the plan.',
   ['Assess the person, space and aids before any move.',
    'Never lift all of a person\'s weight by hand; use hoists and sliding sheets.',
    'Keep floors dry and clear, lights on, call bell within reach.',
    'Report any fall and watch for delayed signs.'],
   'A person weighs 70 kg. Lifting them by hand puts far more than a safe load on the carer; with a hoist, the carer pushes only a small force. Use the aid every time. Check: if the hoist is rated for 150 kg, the 70 kg person is 80 kg under the rating. Steps before the move: read the plan, check the sling and the brakes, tell the person what will happen, use two staff if the plan says so, and clear the path.',
   'Write a moving plan for a bed-to-chair transfer naming the aid, the number of staff, the checks before the move and what to do after.',
   'Plan names aids, number of staff and checks; the person weight is compared with the aid rating; falls-prevention steps are listed and the plan is signed.'),
  ('Nutrition, fluids and elimination', 'Analyse', 4,
   'Enough food and drink keeps people well. Charts show problems early.',
   ['Offer fluids regularly; typical need is 1.5 to 2 litres a day unless a nurse says otherwise.',
    'Seat the person upright to eat and drink safely.',
    'Record intake and output on charts.',
    'Report choking, vomiting, loss of appetite and changes in urine or stool.'],
   'Intake in a day: 6 cups of 200 mL = 1,200 mL, below a 1,500 mL aim by 300 mL. Offer a drink every 2 hours and report if low for two days. The gap of 300 mL is 1.5 cups of 200 mL. Over 12 waking hours, 6 drinks of 250 mL give 6 x 250 = 1,500 mL, which meets the aim. Record every drink at once, not from memory.',
   'Total a fluid chart over a full day, note the gap against the aim, and write which drinks you would offer and when.',
   'Totals correct and low intake reported to the nurse; the gap is stated in mL; drinks are spread across the day and the person sits upright.'),
  ('Infection prevention', 'Evaluate', 3,
   'Hand hygiene is the single most important step to stop infection.',
   ['Clean hands before and after contact, before meals and after toilet.',
    'Wash hands with soap for 20 seconds, covering all surfaces.',
    'Wear gloves for body fluids and change between tasks.',
    'Sort used items and sharps as the facility waste rules require.'],
   'A worker with 15 contacts per shift cleans hands before and after each = 30 hand cleans. A missed one in 10 leaves 3 gaps, each a risk of passing infection. Check: 30 - 3 = 27 cleans done, 27 / 30 = 90 percent. Aim for 100 percent: put hand gel at the bed, clean before gloves and after removing them, and clean again before leaving the room.',
   'Audit hand hygiene steps in order for a task, with the 20-second wash, glove use and waste sorting, and give each gap a fix.',
   'All steps in order and each gap has a fix; the percentage of cleans done is computed correctly; waste and sharps are sorted as the facility rules require.'),
  ('Recognise change and escalate', 'Analyse', 4,
   'Early reporting saves lives. Compare today with the person\'s usual.',
   ['Learn warning signs: new confusion, breathlessness, chest pain, fever, fall, bleeding.',
    'Use a simple report: who, what you saw, when, what you did, what you need.',
    'Call emergency services for severe signs without delay.',
    'Record facts, not guesses.'],
   'Pulse yesterday 72, today 108; temperature 37.0 then 38.2 C. The rise is 36 beats and 1.2 C, so report now using the format and do not wait for the next round. The pulse rose 36 / 72 = 50 percent. Say: who, what you saw, when, what you did and what you need. Write it as facts only, and note the time you told the nurse.',
   'Practise three reports with a partner, using the who, what, when, did and need format, and include the numbers that changed.',
   'Each report is clear, factual and under 60 seconds; all five parts are present; changes are given as numbers; severe signs lead to emergency services.'),
  ('Records, handover and care plan', 'Create', 3,
   'Written records keep care continuous and show what was done.',
   ['Write the time, fact and your name; use plain words.',
    'Keep records private and share only with those who need them.',
    'Make a handover note: changes, needs, risks, to-do.',
    'Follow the data protection rules of the relevant federal rules.'],
   'Handover note for 6 residents in 10 minutes: 100 seconds each. Use the order name, change, risk, task so nothing is missed. Check: 6 x 100 = 600 seconds, which is 10 minutes. Each of the 4 items then gets about 25 seconds. Share the note only with those who need it and keep it out of public view.',
   'Write a handover note for one person from case notes in the order name, change, risk and task, and read it aloud in the time allowed.',
   'Note is accurate, brief and in order; it can be read in under 100 seconds; it holds facts only and respects privacy.'),
 ],
 quiz=[
  ('What is outside a support worker role?', 'Diagnosing and giving medicines or treatments without authority; if asked, say no politely and pass the request to the nurse in charge.'),
  ('Pulse 38 in 30 seconds. Rate?', '38 doubled is 76 per minute; if the pulse feels irregular, count for a full 60 seconds instead and record which method you used.'),
  ('Why count breathing without telling the person?', 'They may change their breathing if they know, so the count would not show the true rate; keep your hand on the wrist and count for 60 seconds.'),
  ('How long to wash hands?', 'About 20 seconds with soap, covering palms, backs, fingers, thumbs and wrists, then dry well with a clean towel.'),
  ('Why reposition at set times?', 'To prevent pressure sores; a plan of every 2 hours gives 12 changes in 24 hours, and each change is signed on the chart.'),
  ('Give a safe moving rule.', 'Use aids and follow the plan; do not lift full weight by hand, check the sling and brakes, and ask for a second person when the plan says so.'),
  ('A person has chest pain and breathlessness. Action?', 'Call emergency services immediately, stay with the person, keep them calm and comfortable, and tell the nurse; do not wait for the next round.'),
  ('What should a report include?', 'Who, what you saw, when, what you did and what you need, in clear facts and numbers, short enough to give in under 60 seconds.'),
  ('Why record facts, not guesses?', 'Facts are reliable and support decisions by the nurse and doctor; a guess such as looks unwell can mislead, but pulse 108 can be checked.'),
  ('A resident refuses a wash. What do you do?', 'Respect the choice, offer another time, keep the person comfortable, record the refusal with the time and tell the nurse before the shift ends.'),
 ],
 rubric=[
  ('Observations', 'Errors above 4 or missing chart.', 'Within 4 and chart complete.', 'Also spots a trend.'),
  ('Dignity and role limits', 'Steps beyond role.', 'Stays in role and respects consent.', 'Also explains reasons to others.'),
  ('Safety', 'Unsafe lifting.', 'Aids and checks named.', 'Also plans falls prevention.'),
  ('Infection control', 'Steps missed.', 'Hand hygiene steps in order.', 'Also audits colleagues kindly.'),
  ('Escalation and records', 'Vague notes.', 'Clear report and handover.', 'Also keeps data private by design.'),
 ],
 ladder=[
  'L1 Basic: Name basic needs of a person in care and when to call help.',
  'L2 Awareness: Explain role limits, dignity and hand hygiene.',
  'L3 Foundation: Take observations and help with hygiene and meals under guidance.',
  'L4 Practitioner: Run a daily care support routine with charts and handover.',
  'L5 Specialist: Lead care workers on a ward or home service under a nurse.',
  'L6 Advanced: Train staff and audit quality (needs formal training).',
  'L7 Super expert: Shape care policy and training (needs formal professional qualifications).',
 ],
 jobs=[
  ('Care assistant', 'Helps with daily living under supervision.'),
  ('Home care worker', 'Supports people in their homes.'),
  ('Ward orderly', 'Moves people and supplies safely.'),
  ('Family carer trainee', 'Learns skills to care at home.'),
  ('Nursing student support', 'Prepares for formal nursing training.'),
 ],
 next='Next courses: Elderly Care, Medical Waste Disposal, and First Aid.',
))
